-- Ordered projections of immutable originals; no second transcript store.
ALTER TABLE conversation_intent ADD COLUMN memory_created_at INTEGER NOT NULL DEFAULT 0;
UPDATE conversation_intent SET memory_created_at=coalesce(CAST(strftime('%s',substr(json_extract(message_json,'$.created_at'),1,19)||CASE WHEN substr(json_extract(message_json,'$.created_at'),-6,1) IN ('+','-') THEN substr(json_extract(message_json,'$.created_at'),-6) ELSE 'Z' END) AS INTEGER)*1000000 + CASE WHEN substr(json_extract(message_json,'$.created_at'),20,1)='.' THEN CAST(round(CAST(substr(json_extract(message_json,'$.created_at'),20) AS REAL)*1000000) AS INTEGER) ELSE 0 END,0);
CREATE INDEX conversation_memory_page ON conversation_intent(json_extract(message_json,'$.conversation_id'),memory_created_at DESC,message_id DESC);
CREATE TRIGGER conversation_memory_time AFTER INSERT ON conversation_intent BEGIN UPDATE conversation_intent SET memory_created_at=coalesce(CAST(strftime('%s',substr(json_extract(NEW.message_json,'$.created_at'),1,19)||CASE WHEN substr(json_extract(NEW.message_json,'$.created_at'),-6,1) IN ('+','-') THEN substr(json_extract(NEW.message_json,'$.created_at'),-6) ELSE 'Z' END) AS INTEGER)*1000000 + CASE WHEN substr(json_extract(NEW.message_json,'$.created_at'),20,1)='.' THEN CAST(round(CAST(substr(json_extract(NEW.message_json,'$.created_at'),20) AS REAL)*1000000) AS INTEGER) ELSE 0 END,0) WHERE sequence=NEW.sequence; END;
CREATE TRIGGER conversation_memory_time_immutable BEFORE UPDATE OF memory_created_at ON conversation_intent WHEN OLD.memory_created_at<>0 AND NEW.memory_created_at<>OLD.memory_created_at BEGIN SELECT RAISE(ABORT,'immutable message time projection'); END;
ALTER TABLE memory_dream_coverage ADD COLUMN worker_sequence INTEGER NOT NULL DEFAULT 0 CHECK(worker_sequence>=0);
ALTER TABLE memory_dream_coverage ADD COLUMN worker_offset INTEGER NOT NULL DEFAULT 0 CHECK(worker_offset>=0);
